mapper.update:
update sensor_devices set serial_number = #{serialNumber},
model = #{model}, firmware_version = #{firmwareVersion}
model = coalesce(model, #{model}), firmware_version = coalesce(firmware_version, #{firmwareVersion})
where id = #{sensorId}

mapper.select:
select exists (
    select 1
    from user_device_selections
    where device_id = #{bedId}
      and user_id = #{userId}
      and selected_at <= #{startedAt}
)

select boot_id, schema_version, sequence_number, repetition_count, received_at
from sensor_latest_readings
where sensor_id = #{sensorId}

select exists (
    select 1
    from sensor_boots
    where sensor_id = #{sensorId}
      and boot_id = #{bootId}
)

select id, boot_id, summary_received, end_count, active_duration_ms,
       started_at, time_quality, status, time_valid, summary_payload_json
from sensor_workout_sessions
where sensor_id = #{sensorId}
  and device_session_id = #{sessionId}
for update

mapper.update:
update sensor_devices
set last_seen_at = #{lastSeenAt}
where id = #{sensorId}
